INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df2a9b50-6570-11f1-9578-071530b96ddb', 1781167088005, NULL, 'org.thingsboard.rule.engine.transform.TbDeleteKeysNode', '{"nodeDefinition":{"details":"Deletes key-value pairs from the message or message metadata according to the configured keys and/or regular expressions.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Deletes key-value pairs from message or message metadata.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"deleteFrom":"DATA","keys":[]},"uiResources":[],"configDirective":"tbTransformationNodeDeleteKeysConfig","icon":"remove_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/delete-key-value-pairs/"}}', 2, 'delete key-value pairs', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df83b7d0-6570-11f1-9578-071530b96ddb', 1781167088589, NULL, 'org.thingsboard.rule.engine.aws.sqs.TbSqsNode', '{"nodeDefinition":{"details":"Will publish message payload and metadata attributes to the AWS SQS queue. Outbound message will contain response fields (<code>messageId</code>, <code>requestId</code>, <code>messageBodyMd5</code>, <code>messageAttributesMd5</code>, <code>sequenceNumber</code>) in the Message Metadata from the AWS SQS. For example <b>requestId</b> field can be accessed with <code>metadata.requestId</code>.","description":"Publish messages to the AWS SQS","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"queueType":"STANDARD","queueUrlPattern":"https://sqs.us-east-1.amazonaws.com/123456789012/my-queue-name","delaySeconds":0,"messageAttributes":{},"accessKeyId":null,"secretAccessKey":null,"region":"us-east-1"},"uiResources":[],"configDirective":"tbExternalNodeSqsConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/aws-sqs/"}}', 0, 'aws sqs', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df86ec20-6570-11f1-9578-071530b96ddb', 1781167088610, NULL, 'org.thingsboard.rule.engine.edge.TbMsgPushToEdgeNode', '{"nodeDefinition":{"details":"Push messages from cloud to edge. Message originator must be assigned to particular edge or message originator is <b>EDGE</b> entity itself. This node used only on cloud instances to push messages from cloud to edge. Once message arrived into this node it’s going to be converted into edge event and saved to the database. Node doesn''t push messages directly to edge, but stores event(s) in the edge queue. Supports next message types:<br><code>POST_TELEMETRY_REQUEST</code><br><code>POST_ATTRIBUTES_REQUEST</code><br><code>ATTRIBUTES_UPDATED</code><br><code>ATTRIBUTES_DELETED</code><br><code>ALARM</code><br><br>Message will be routed via <b>Failure</b> route if node was not able to save edge event to database or unsupported message type arrived. In case successful storage edge event to database message will be routed via <b>Success</b> route.","description":"Push messages from cloud to edge","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scope":"SERVER_SCOPE"},"uiResources":[],"configDirective":"tbActionNodePushToEdgeConfig","icon":"cloud_download","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/push-to-edge/"}}', 0, 'push to edge', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df893610-6570-11f1-9578-071530b96ddb', 1781167088625, NULL, 'org.thingsboard.rule.engine.action.TbLogNode', '{"nodeDefinition":{"details":"Transform incoming Message with configured JS function to String and log final value into Thingsboard log file. Message payload can be accessed via <code>msg</code> property. For example <code>''temperature = '' + msg.temperature ;</code>. Message metadata can be accessed via <code>metadata</code> property. For example <code>''name = '' + metadata.customerName;</code>.","description":"Log incoming messages using JS script for transformation Message into String","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scriptLang":"TBEL","jsScript":"return ''\\nIncoming message:\\n'' + JSON.stringify(msg) + ''\\nIncoming metadata:\\n'' + JSON.stringify(metadata);","tbelScript":"return ''\\nIncoming message:\\n'' + JSON.stringify(msg) + ''\\nIncoming metadata:\\n'' + JSON.stringify(metadata);"},"uiResources":[],"configDirective":"tbActionNodeLogConfig","icon":"menu","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/log/"}}', 0, 'log', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df8bf530-6570-11f1-9578-071530b96ddb', 1781167088643, NULL, 'org.thingsboard.rule.engine.action.TbClearAlarmNode', '{"nodeDefinition":{"details":"Details - JS function that creates JSON object based on incoming message. This object will be added into Alarm.details field.\nNode output:\nIf alarm was not cleared, original message is returned. Otherwise new Message returned with type ''ALARM'', Alarm object in ''msg'' property and ''metadata'' will contains ''isClearedAlarm'' property.\nMessage payload can be accessed via <code>msg</code> property. For example <code>''temperature = '' + msg.temperature ;</code>.\nMessage metadata can be accessed via <code>metadata</code> property. For example <code>''name = '' + metadata.customerName;</code>.","description":"Clear Alarm","inEnabled":true,"outEnabled":true,"relationTypes":["Cleared","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"alarmType":"General Alarm","scriptLang":"TBEL","alarmDetailsBuildJs":"var details = {};\nif (metadata.prevAlarmDetails) {\n    details = JSON.parse(metadata.prevAlarmDetails);\n    //remove prevAlarmDetails from metadata\n    delete metadata.prevAlarmDetails;\n    //now metadata is the same as it comes IN this rule node\n}\n\n\nreturn details;","alarmDetailsBuildTbel":"var details = {};\nif (metadata.prevAlarmDetails != null) {\n    details = JSON.parse(metadata.prevAlarmDetails);\n    //remove prevAlarmDetails from metadata\n    metadata.remove(''prevAlarmDetails'');\n    //now metadata is the same as it comes IN this rule node\n}\n\n\nreturn details;"},"uiResources":[],"configDirective":"tbActionNodeClearAlarmConfig","icon":"notifications_off","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/clear-alarm/"}}', 0, 'clear alarm', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df8e8d40-6570-11f1-9578-071530b96ddb', 1781167088660, NULL, 'org.thingsboard.rule.engine.mail.TbSendEmailNode', '{"nodeDefinition":{"details":"Expects messages with <b>SEND_EMAIL</b> type. Node works only with messages that  where created using <code>to Email</code> transformation Node, please connect this Node with <code>to Email</code> Node using <code>Successful</code> chain.","description":"Sends email message via SMTP server.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"useSystemSmtpSettings":true,"smtpHost":"localhost","smtpPort":25,"username":null,"password":null,"smtpProtocol":"smtp","timeout":10000,"enableTls":false,"tlsVersion":"TLSv1.2","enableProxy":false,"proxyHost":null,"proxyPort":null,"proxyUser":null,"proxyPassword":null},"uiResources":[],"configDirective":"tbExternalNodeSendEmailConfig","icon":"send","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/send-email/"}}', 0, 'send email', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df940b80-6570-11f1-9578-071530b96ddb', 1781167088696, NULL, 'org.thingsboard.rule.engine.sms.TbSendSmsNode', '{"nodeDefinition":{"details":"Will send SMS message by populating target phone numbers and sms message fields using values derived from message metadata.","description":"Sends SMS message via SMS provider.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"numbersToTemplate":"${userPhone}","smsMessageTemplate":"Device ${deviceName} has high temperature ${temp}","useSystemSmsSettings":true,"smsProviderConfiguration":null},"uiResources":[],"configDirective":"tbExternalNodeSendSmsConfig","icon":"sms","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/send-sms/"}}', 0, 'send sms', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df9962b0-6570-11f1-9578-071530b96ddb', 1781167088731, NULL, 'org.thingsboard.rule.engine.ai.TbAiNode', '{"nodeDefinition":{"details":"Interact with large language models (LLMs) by sending dynamic requests from your rule chain.\nYou can select a specific <strong>AI model</strong> and define its behavior using a <strong>system prompt</strong> (optional context or role) and a <strong>user prompt</strong> (the main task).\nBoth prompts can be populated with data and metadata from the incoming message using patterns.\nFor example, the <code>$[*]</code> and <code>${*}</code> patterns allow you to access the all message body and all metadata, respectively.\n<br><br>\nAfter sending the request, the node waits for a response within a configured <strong>timeout</strong>.\nYou can specify the desired <strong>response format</strong> as <strong>Text</strong>, <strong>JSON</strong>, or provide a specific <strong>JSON Schema</strong> to structure the output.\nThe AI-generated content is forwarded as the body of the outgoing message; the originator, message type, and metadata from the incoming message remain unchanged.\n<br><br>\nOutput connections: <code>Success</code>, <code>Failure</code>.\n","description":"Sends a request to an AI model using system and user prompts. Supports JSON mode.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"modelId":null,"systemPrompt":"You are a helpful AI assistant. Your primary function is to process the user''s request and respond with a valid JSON object. Do not include any text, explanations, or markdown formatting before or after the JSON output.","userPrompt":null,"resourceIds":null,"responseFormat":{"type":"JSON"},"timeoutSeconds":60,"forceAck":true},"uiResources":[],"configDirective":"tbExternalNodeAiConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/ai-request/"}}', 0, 'AI request', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df9bfac0-6570-11f1-9578-071530b96ddb', 1781167088748, NULL, 'org.thingsboard.rule.engine.deduplication.TbMsgDeduplicationNode', '{"nodeDefinition":{"details":"Deduplication strategies: <ul><li><strong>FIRST</strong> - return first message that arrived during deduplication period.</li><li><strong>LAST</strong> - return last message that arrived during deduplication period.</li><li><strong>ALL</strong> - return all messages as a single JSON array message. Where each element represents object with <strong><i>msg</i></strong> and <strong><i>metadata</i></strong> inner properties.</li></ul>","description":"Deduplicate messages within the same originator entity for a configurable period based on a specified deduplication strategy.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"interval":60,"strategy":"FIRST","outMsgType":null,"maxPendingMsgs":100,"maxRetries":3},"uiResources":[],"configDirective":"tbTransformationNodeDeduplicationConfig","icon":"content_copy","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/deduplication/"}}', 1, 'deduplication', 'TENANT', 'TRANSFORMATION', 'ENABLED', 't');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('df9e1da0-6570-11f1-9578-071530b96ddb', 1781167088762, NULL, 'org.thingsboard.rule.engine.telemetry.TbCalculatedFieldsNode', '{"nodeDefinition":{"details":"Node enables the processing of calculated fields and alarm rules without persisting incoming messages to the database. By default, the processing of calculated fields and alarm rules is triggered by the <b>save attributes</b> and <b>save time series</b> nodes. This rule node accepts the same messages as these nodes but allows you to trigger the processing of calculated fields or alarm rules independently, ensuring that derived data can be computed and utilized in real time without storing the original message in the database.","description":"Pushes incoming messages to calculated fields and alarm rules services","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"published_with_changes","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/calculated-fields/"}}', 0, 'calculated fields and alarm rules', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfa01970-6570-11f1-9578-071530b96ddb', 1781167088775, NULL, 'org.thingsboard.rule.engine.transform.TbJsonPathNode', '{"nodeDefinition":{"details":"JSONPath expression specifies a path to an element or a set of elements in a JSON structure.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Transforms incoming message body using JSONPath expression.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"jsonPath":"$"},"uiResources":[],"configDirective":"tbTransformationNodeJsonPathConfig","icon":"functions","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/json-path/"}}', 0, 'json path', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfa26360-6570-11f1-9578-071530b96ddb', 1781167088790, NULL, 'org.thingsboard.rule.engine.action.TbDeleteRelationNode', '{"nodeDefinition":{"details":"Useful when you need to remove relations between entities dynamically depending on incoming message payload, message originator type, name, etc.<br><br>If <strong>Delete relation with specific entity</strong> enabled, target entity to delete relation with should be specified. Otherwise, rule node will delete all relations with the message originator based on the configured direction and type.<br><br>Target entity configuration: <ul><li><strong>Device</strong> - use a device with the specified name as the target entity to delete relation with.</li><li><strong>Asset</strong> - use an asset with the specified name as the target entity to delete relation with.</li><li><strong>Entity View</strong> - use entity view with the specified name as the target entity to delete relation with.</li><li><strong>Tenant</strong> - use current tenant as target entity to delete relation with.</li><li><strong>Customer</strong> - use customer with the specified title as the target entity to delete relation with.</li><li><strong>Dashboard</strong> - use a dashboard with the specified title as the target entity to delete relation with.</li><li><strong>User</strong> - use a user with the specified email as the target entity to delete relation with.</li><li><strong>Edge</strong> - use an edge with the specified name as the target entity to delete relation with.</li></ul>Output connections: <code>Success</code> - If the relation(s) successfully deleted, otherwise <code>Failure</code>.","description":"Deletes relation with the incoming message originator based on the configured direction and type.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"direction":"FROM","relationType":"Contains","entityType":null,"entityNamePattern":"","entityTypePattern":null,"deleteForSingleEntity":false},"uiResources":[],"configDirective":"tbActionNodeDeleteRelationConfig","icon":"remove_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/delete-relation/"}}', 1, 'delete relation', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfa48640-6570-11f1-9578-071530b96ddb', 1781167088804, NULL, 'org.thingsboard.rule.engine.filter.TbJsSwitchNode', '{"nodeDefinition":{"details":"Node executes configured TBEL(recommended) or JavaScript function that returns array of strings (connection names). If Array is empty - message not routed to next Node. Message payload can be accessed via <code>msg</code> property. For example <code>msg.temperature < 10;</code><br/>Message metadata can be accessed via <code>metadata</code> property. For example <code>metadata.customerName === ''John'';</code><br/>Message type can be accessed via <code>msgType</code> property.<br><br>Output connections: <i>Custom connection(s) defined by switch node</i> or <code>Failure</code>","description":"Routes incoming message to one OR multiple output connections.","inEnabled":true,"outEnabled":true,"relationTypes":["Failure"],"customRelations":true,"ruleChainNode":false,"defaultConfiguration":{"scriptLang":"TBEL","jsScript":"function nextRelation(metadata, msg) {\n    return [''one'',''nine''];\n}\nif(msgType === ''POST_TELEMETRY_REQUEST'') {\n    return [''two''];\n}\nreturn nextRelation(metadata, msg);","tbelScript":"function nextRelation(metadata, msg) {\n    return [''one'',''nine''];\n}\nif(msgType == ''POST_TELEMETRY_REQUEST'') {\n    return [''two''];\n}\nreturn nextRelation(metadata, msg);"},"uiResources":[],"configDirective":"tbFilterNodeSwitchConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/switch/"}}', 0, 'switch', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfa71e50-6570-11f1-9578-071530b96ddb', 1781167088821, NULL, 'org.thingsboard.rule.engine.telemetry.TbMsgDeleteAttributesNode', '{"nodeDefinition":{"details":"Attempt to remove attributes by selected keys. If msg originator doesn''t have an attribute with  a key selected in the configuration, it will be ignored. If delete operation is completed successfully,  rule node will send the \"Attributes Deleted\" event to the root chain of the message originator and  send the incoming message via <b>Success</b> chain, otherwise, <b>Failure</b> chain is used.","description":"Delete attributes for Message Originator.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scope":"SERVER_SCOPE","keys":[],"sendAttributesDeletedNotification":false,"notifyDevice":false},"uiResources":[],"configDirective":"tbActionNodeDeleteAttributesConfig","icon":"remove_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/delete-attributes/"}}', 0, 'delete attributes', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfa8f310-6570-11f1-9578-071530b96ddb', 1781167088833, NULL, 'org.thingsboard.rule.engine.filter.TbDeviceTypeSwitchNode', '{"nodeDefinition":{"details":"Route incoming messages based on the name of the device profile. The device profile name is case-sensitive<br><br>Output connections: <i>Device profile name</i> or <code>Failure</code>","description":"Route incoming messages based on the name of the device profile","inEnabled":true,"outEnabled":true,"relationTypes":["default","Failure"],"customRelations":true,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/device-profile-switch/"}}', 0, 'device profile switch', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfaaeee0-6570-11f1-9578-071530b96ddb', 1781167088846, NULL, 'org.thingsboard.rule.engine.filter.TbOriginatorTypeSwitchNode', '{"nodeDefinition":{"details":"Routes messages to chain according to the entity type (''Device'', ''Asset'', etc.).<br><br>Output connections: <i>Message originator type</i> or <code>Failure</code>","description":"Route incoming messages by Message Originator Type","inEnabled":true,"outEnabled":true,"relationTypes":["Tenant","Customer","User","Dashboard","Asset","Device","Alarm","Rule chain","Rule node","Entity View","Widgets bundle","Widget type","Tenant profile","Device profile","Asset profile","Api usage state","Resource","Ota package","Edge","Rpc","Queue","Notification target","Notification template","Notification request","Notification","Notification rule","Queue stats","Oauth2 client","Domain","Mobile app","Mobile app bundle","Calculated field","Job","Admin settings","AI model","Api key","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/entity-type-switch/"}}', 0, 'entity type switch', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfadae00-6570-11f1-9578-071530b96ddb', 1781167088864, NULL, 'org.thingsboard.rule.engine.metadata.TbGetTelemetryNode', '{"nodeDefinition":{"details":"Useful when you need to get telemetry data set from the message originator for a specific time range instead of fetching just the latest telemetry or if you need to get the closest telemetry to the fetch interval start or end. Also, this node can be used for telemetry aggregation within configured fetch interval.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator telemetry for selected time range into message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"startInterval":2,"endInterval":1,"startIntervalPattern":"","endIntervalPattern":"","useMetadataIntervalPatterns":false,"startIntervalTimeUnit":"MINUTES","endIntervalTimeUnit":"MINUTES","fetchMode":"FIRST","orderBy":"ASC","aggregation":"NONE","limit":1000,"latestTsKeyNames":[]},"uiResources":[],"configDirective":"tbEnrichmentNodeGetTelemetryFromDatabase","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/originator-telemetry/"}}', 2, 'originator telemetry', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfaff7f0-6570-11f1-9578-071530b96ddb', 1781167088879, NULL, 'org.thingsboard.rule.engine.aws.lambda.TbAwsLambdaNode', '{"nodeDefinition":{"details":"Publishes messages to AWS Lambda, a service that lets you run code without provisioning or managing servers. It sends messages using a RequestResponse invocation type. The node uses a pre-configured client and specified function to run.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Publish message to the AWS Lambda","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"accessKey":null,"secretKey":null,"region":"us-east-1","functionName":null,"qualifier":"$LATEST","connectionTimeout":10,"requestTimeout":5,"tellFailureIfFuncThrowsExc":false},"uiResources":[],"configDirective":"tbExternalNodeLambdaConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/aws-lambda/"}}', 0, 'aws lambda', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfb241e0-6570-11f1-9578-071530b96ddb', 1781167088894, NULL, 'org.thingsboard.rule.engine.transform.TbRenameKeysNode', '{"nodeDefinition":{"details":"Renames keys in the message or message metadata according to the provided mapping. If key to rename doesn''t exist in the specified source (message or message metadata) it will be ignored.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Renames message or message metadata keys.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"renameIn":"DATA","renameKeysMapping":{"temperatureCelsius":"temperature"}},"uiResources":[],"configDirective":"tbTransformationNodeRenameKeysConfig","icon":"find_replace","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/rename-keys/"}}', 2, 'rename keys', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfb4b2e0-6570-11f1-9578-071530b96ddb', 1781167088910, NULL, 'org.thingsboard.rule.engine.edge.TbMsgPushToCloudNode', '{"nodeDefinition":{"details":"Push messages from edge to cloud. This node used only on edge to push messages from edge to cloud. Once message arrived into this node it’s going to be converted into cloud event and saved to the local database. Node doesn''t push messages directly to cloud, but stores event(s) in the cloud queue. Supports next message types:<br><code>POST_TELEMETRY_REQUEST</code><br><code>POST_ATTRIBUTES_REQUEST</code><br><code>ATTRIBUTES_UPDATED</code><br><code>ATTRIBUTES_DELETED</code><br><code>ALARM</code><br><br>Message will be routed via <b>Failure</b> route if node was not able to save cloud event to database or unsupported originator type/message type arrived. In case successful storage cloud event to database message will be routed via <b>Success</b> route.","description":"Pushes messages from edge to cloud","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scope":"SERVER_SCOPE"},"uiResources":[],"configDirective":"tbActionNodePushToCloudConfig","icon":"cloud_upload","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/push-to-cloud/"}}', 0, 'push to cloud', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfb6fcd0-6570-11f1-9578-071530b96ddb', 1781167088925, NULL, 'org.thingsboard.rule.engine.metadata.TbGetAttributesNode', '{"nodeDefinition":{"details":"Useful when you need to retrieve some attributes or the latest telemetry readings from the message originator that are not included in the incoming message to use them for further message processing. For example to filter messages based on the threshold value stored in the attributes.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds attributes and/or latest timeseries data for the message originator to the message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","clientAttributeNames":[],"sharedAttributeNames":[],"serverAttributeNames":[],"latestTsKeyNames":[],"tellFailureIfAbsent":true,"getLatestValueWithTs":false},"uiResources":[],"configDirective":"tbEnrichmentNodeOriginatorAttributesConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/originator-attributes/"}}', 1, 'originator attributes', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfb946c0-6570-11f1-9578-071530b96ddb', 1781167088940, NULL, 'org.thingsboard.rule.engine.filter.TbMsgTypeFilterNode', '{"nodeDefinition":{"details":"If incoming message type is expected - send Message via <b>True</b> chain, otherwise <b>False</b> chain is used.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Filter incoming messages by Message Type","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"messageTypes":["POST_ATTRIBUTES_REQUEST","POST_TELEMETRY_REQUEST","TO_SERVER_RPC_REQUEST"]},"uiResources":[],"configDirective":"tbFilterNodeMessageTypeConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/message-type-filter/"}}', 0, 'message type filter', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfbb4290-6570-11f1-9578-071530b96ddb', 1781167088953, NULL, 'org.thingsboard.rule.engine.action.TbCopyAttributesToEntityViewNode', '{"nodeDefinition":{"details":"Copy attributes from asset/device to related entity view according to entity view configuration. \n Copy will be done only for attributes that are between start and end dates and according to attribute keys configuration. \nChanges message originator to related entity view and produces new messages according to count of updated entity views","description":"Copy attributes from asset/device to entity view and changes message originator to related entity view","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"content_copy","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/copy-to-view/"}}', 0, 'copy to view', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfbe28c0-6570-11f1-9578-071530b96ddb', 1781167088972, NULL, 'org.thingsboard.rule.engine.metadata.TbGetRelatedAttributeNode', '{"nodeDefinition":{"details":"Related entity lookup based on the configured relation query. If multiple related entities are found, only first entity is used for message enrichment, other entities are discarded. Useful when you need to retrieve data from an entity that has a relation to the message originator and use them for further message processing.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds originators related entity attributes or latest telemetry or fields into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","dataMapping":{"serialNumber":"sn"},"dataToFetch":"ATTRIBUTES","relationsQuery":{"direction":"FROM","maxLevel":1,"filters":[{"relationType":"Contains","entityTypes":[],"negate":false}],"fetchLastLevelOnly":false}},"uiResources":[],"configDirective":"tbEnrichmentNodeRelatedAttributesConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/related-entity-data/"}}', 1, 'related entity data', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfc02490-6570-11f1-9578-071530b96ddb', 1781167088985, NULL, 'org.thingsboard.rule.engine.action.TbMsgCountNode', '{"nodeDefinition":{"details":"Count incoming messages for specified interval and produces POST_TELEMETRY_REQUEST msg with messages count","description":"Count incoming messages","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"telemetryPrefix":"messageCount","interval":1},"uiResources":[],"configDirective":"tbActionNodeMsgCountConfig","icon":"functions","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/message-count/"}}', 0, 'message count', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfc22060-6570-11f1-9578-071530b96ddb', 1781167088998, NULL, 'org.thingsboard.rule.engine.transaction.TbSynchronizationBeginNode', '{"nodeDefinition":{"details":"This node should be used together with \"synchronization end\" node. \n This node will put messages into queue based on message originator id. \nSubsequent messages will not be processed until the previous message processing is completed or timeout event occurs.\nSize of the queue per originator and timeout values are configurable on a system level","description":"This Node is now deprecated. Use \"Checkpoint\" instead.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":""}}', 0, 'synchronization start', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfc41c30-6570-11f1-9578-071530b96ddb', 1781167089011, NULL, 'org.thingsboard.rule.engine.flow.TbRuleChainOutputNode', '{"nodeDefinition":{"details":"Produces output of the rule chain processing. The output is forwarded to the caller rule chain, as an output of the corresponding \"input\" rule node. The output rule node name corresponds to the relation type of the output message, and it is used to forward messages to other rule nodes in the caller rule chain. ","description":"transfers the message to the caller rule chain","inEnabled":true,"outEnabled":false,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbFlowNodeRuleChainOutputConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/flow/output/"}}', 0, 'output', 'TENANT', 'FLOW', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfc5f0f0-6570-11f1-9578-071530b96ddb', 1781167089023, NULL, 'org.thingsboard.rule.engine.filter.TbAssetTypeSwitchNode', '{"nodeDefinition":{"details":"Route incoming messages based on the name of the asset profile. The asset profile name is case-sensitive.<br><br>Output connections: <i>Asset profile name</i> or <code>Failure</code>","description":"Route incoming messages based on the name of the asset profile","inEnabled":true,"outEnabled":true,"relationTypes":["default","Failure"],"customRelations":true,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/asset-profile-switch/"}}', 0, 'asset profile switch', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfc7ecc0-6570-11f1-9578-071530b96ddb', 1781167089036, NULL, 'org.thingsboard.rule.engine.filter.TbJsFilterNode', '{"nodeDefinition":{"details":"Evaluates boolean function using incoming message. The function may be written using TBEL or plain JavaScript. Script function should return boolean value and accepts three parameters: <br/>Message payload can be accessed via <code>msg</code> property. For example <code>msg.temperature < 10;</code><br/>Message metadata can be accessed via <code>metadata</code> property. For example <code>metadata.customerName === ''John'';</code><br/>Message type can be accessed via <code>msgType</code> property.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Filter incoming messages using TBEL or JS script","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scriptLang":"TBEL","jsScript":"return msg.temperature > 20;","tbelScript":"return msg.temperature > 20;"},"uiResources":[],"configDirective":"tbFilterNodeScriptConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/script/"}}', 0, 'script', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfca36b0-6570-11f1-9578-071530b96ddb', 1781167089051, NULL, 'org.thingsboard.rule.engine.rpc.TbSendRPCRequestNode', '{"nodeDefinition":{"details":"Expects messages with \"method\" and \"params\". Will forward response from device to next nodes.If the RPC call request is originated by REST API call from user, will forward the response to user immediately.","description":"Sends RPC call to device","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"timeoutInSeconds":60},"uiResources":[],"configDirective":"tbActionNodeRpcRequestConfig","icon":"call_made","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/rpc-call-request/"}}', 0, 'rpc call request', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfcdb920-6570-11f1-9578-071530b96ddb', 1781167089074, NULL, 'org.thingsboard.rule.engine.math.TbMathNode', '{"nodeDefinition":{"details":"Supports math operations like: ADD, SUB, MULT, DIV, etc and functions: SIN, COS, TAN, SEC, etc. Use ''CUSTOM'' operation to specify complex math expressions.<br/><br/>You may use constant, message field, metadata field, attribute, and latest time-series as an arguments values. The result of the function may be also stored to message field, metadata field, attribute or time-series value.<br/><br/>Primary use case for this rule node is to take one or more values from the database and modify them based on data from the message. For example, you may increase `totalWaterConsumption` based on the `deltaWaterConsumption` reported by device.<br/><br/>Alternative use case is the replacement of simple JS `script` nodes with more light-weight and performant implementation. For example, you may transform Fahrenheit to Celsius (C = (F - 32) / 1.8) using CUSTOM operation and expression: (x - 32) / 1.8).<br/><br/>The execution is synchronized in scope of message originator (e.g. device) and server node. If you have rule nodes in different rule chains, they will process messages from the same originator synchronously in the scope of the server node.","description":"Apply math function and save the result into the message and/or database","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"operation":"CUSTOM","arguments":[{"name":"x","type":"MESSAGE_BODY","key":"temperature","attributeScope":null,"defaultValue":null}],"customFunction":"(x - 32) / 1.8","result":{"type":"MESSAGE_BODY","key":"temperatureCelsius","resultValuePrecision":2,"addToBody":false,"addToMetadata":false,"attributeScope":null}},"uiResources":[],"configDirective":"tbActionNodeMathFunctionConfig","icon":"calculate","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/math-function/"}}', 0, 'math function', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfcf8de0-6570-11f1-9578-071530b96ddb', 1781167089086, NULL, 'org.thingsboard.rule.engine.rest.TbSendRestApiCallReplyNode', '{"nodeDefinition":{"details":"Expects messages with any message type. Forwards incoming message as a reply to REST API call sent to rule engine.","description":"Sends reply to REST API call to rule engine","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"serviceIdMetaDataAttribute":"serviceId","requestIdMetaDataAttribute":"requestUUID"},"uiResources":[],"configDirective":"tbActionNodeSendRestApiCallReplyConfig","icon":"call_merge","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/rest-call-reply/"}}', 0, 'rest call reply', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfd189b0-6570-11f1-9578-071530b96ddb', 1781167089099, NULL, 'org.thingsboard.rule.engine.transform.TbTransformMsgNode', '{"nodeDefinition":{"details":"JavaScript function receive 3 input parameters <br/> <code>msg</code> - is a message payload.<br/><code>metadata</code> - is a message metadata.<br/><code>msgType</code> - is a message type.<br/>Should return the following structure:<br/><code>{ msg: <i style=\"color: #666;\">new payload</i>,<br/>&nbsp&nbsp&nbspmetadata: <i style=\"color: #666;\">new metadata</i>,<br/>&nbsp&nbsp&nbspmsgType: <i style=\"color: #666;\">new msgType</i> }</code><br/>All fields in resulting object are optional and will be taken from original message if not specified.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Change Message payload, Metadata or Message type using JavaScript","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"scriptLang":"TBEL","jsScript":"return {msg: msg, metadata: metadata, msgType: msgType};","tbelScript":"return {msg: msg, metadata: metadata, msgType: msgType};"},"uiResources":[],"configDirective":"tbTransformationNodeScriptConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/script/"}}', 0, 'script', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfd33760-6570-11f1-9578-071530b96ddb', 1781167089110, NULL, 'org.thingsboard.rule.engine.filter.TbMsgTypeSwitchNode', '{"nodeDefinition":{"details":"Sends messages with message types <b>\"Post attributes\", \"Post telemetry\", \"RPC Request\"</b> etc. via corresponding chain, otherwise <b>Other</b> chain is used.<br><br>Output connections: <i>Message type connection</i>, <code>Other</code> - if message type is custom or <code>Failure</code>","description":"Route incoming messages by Message Type","inEnabled":true,"outEnabled":true,"relationTypes":["Post attributes","Post telemetry","RPC Request from Device","Activity Event","Inactivity Event","Connect Event","Disconnect Event","Entity Created","Entity Updated","Entity Deleted","Entity Assigned","Entity Unassigned","Attributes Updated","Attributes Deleted","Alarm","Alarm Created","Alarm Updated","Alarm Severity Updated","Alarm Acknowledged","Alarm Cleared","Alarm Assigned","Alarm Unassigned","Comment Created","Comment Updated","RPC Request to Device","Entity Assigned From Tenant","Entity Assigned To Tenant","Timeseries Updated","Timeseries Deleted","RPC Queued","RPC Sent","RPC Delivered","RPC Successful","RPC Timeout","RPC Expired","RPC Failed","RPC Deleted","Relation Added or Updated","Relation Deleted","All Relations Deleted","REST API request","Other","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/message-type-switch/"}}', 0, 'message type switch', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfd53330-6570-11f1-9578-071530b96ddb', 1781167089123, NULL, 'org.thingsboard.rule.engine.metadata.TbFetchDeviceCredentialsNode', '{"nodeDefinition":{"details":"if message originator type is Device and device credentials was successfully fetched, rule node enriches message or message metadata with <i>credentialsType</i> and <i>credentials</i> properties. Useful when you need to fetch device credentials and use them for further message processing. For example, use device credentials to interact with external systems.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds device credentials to the message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA"},"uiResources":[],"configDirective":"tbEnrichmentNodeFetchDeviceCredentialsConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/fetch-device-credentials/"}}', 1, 'fetch device credentials', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfd75610-6570-11f1-9578-071530b96ddb', 1781167089137, NULL, 'org.thingsboard.rule.engine.debug.TbMsgGeneratorNode', '{"nodeDefinition":{"details":"Generates messages with configurable period. Javascript function used for message generation.","description":"Periodically generates messages","inEnabled":false,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"msgCount":0,"periodInSeconds":1,"originatorId":null,"originatorType":"RULE_NODE","scriptLang":"TBEL","jsScript":"var msg = { temp: 42, humidity: 77 };\nvar metadata = { data: 40 };\nvar msgType = \"POST_TELEMETRY_REQUEST\";\n\nreturn { msg: msg, metadata: metadata, msgType: msgType };","tbelScript":"var msg = { temp: 42, humidity: 77 };\nvar metadata = { data: 40 };\nvar msgType = \"POST_TELEMETRY_REQUEST\";\n\nreturn { msg: msg, metadata: metadata, msgType: msgType };"},"uiResources":[],"configDirective":"tbActionNodeGeneratorConfig","icon":"repeat","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/generator/"}}', 2, 'generator', 'TENANT', 'ACTION', 'ENABLED', 't');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfd92ad0-6570-11f1-9578-071530b96ddb', 1781167089149, NULL, 'org.thingsboard.rule.engine.filter.TbCheckRelationNode', '{"nodeDefinition":{"details":"If ''check relation to specific entity'' is selected, you should specify a related entity. Otherwise, the rule node checks the presence of a relation to any entity. In both cases, relation lookup is based on configured direction and type.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Checks the presence of the relation between the originator of the message and other entities.","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"direction":"FROM","entityId":null,"entityType":null,"relationType":"Contains","checkForSingleEntity":true},"uiResources":[],"configDirective":"tbFilterNodeCheckRelationConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/check-relation-presence/"}}', 1, 'check relation presence', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfdb26a0-6570-11f1-9578-071530b96ddb', 1781167089162, NULL, 'org.thingsboard.rule.engine.profile.TbDeviceProfileNode', '{"nodeDefinition":{"details":"Create and clear alarms based on alarm rules defined in device profile. The output relation type is either ''Alarm Created'', ''Alarm Updated'', ''Alarm Severity Updated'' and ''Alarm Cleared'' or simply ''Success'' if no alarms were affected.","description":"Process device messages based on device profile settings (deprecated)","inEnabled":true,"outEnabled":true,"relationTypes":["Alarm Created","Alarm Updated","Alarm Severity Updated","Alarm Cleared","Success","Failure"],"customRelations":true,"ruleChainNode":false,"defaultConfiguration":{"persistAlarmRulesState":false,"fetchAlarmRulesStateOnStart":false},"uiResources":[],"configDirective":"tbActionNodeDeviceProfileConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/device-profile/"}}', 1, 'device profile (deprecated)', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfdcad40-6570-11f1-9578-071530b96ddb', 1781167089172, NULL, 'org.thingsboard.rule.engine.filter.TbOriginatorTypeFilterNode', '{"nodeDefinition":{"details":"Checks that the entity type of the incoming message originator matches one of the values specified in the filter.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Filter incoming messages by the type of message originator entity","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"originatorTypes":["DEVICE"]},"uiResources":[],"configDirective":"tbFilterNodeOriginatorTypeConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/entity-type-filter/"}}', 0, 'entity type filter', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfde5af0-6570-11f1-9578-071530b96ddb', 1781167089183, NULL, 'org.thingsboard.rule.engine.flow.TbCheckpointNode', '{"nodeDefinition":{"details":"After successful transfer incoming message is automatically acknowledged. Queue name is configurable.","description":"transfers the message to another queue","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/flow/checkpoint/"}}', 1, 'checkpoint', 'TENANT', 'FLOW', 'ENABLED', 't');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfe0a4e0-6570-11f1-9578-071530b96ddb', 1781167089198, NULL, 'org.thingsboard.rule.engine.transform.TbChangeOriginatorNode', '{"nodeDefinition":{"details":"Configuration: <ul><li><strong>Customer</strong> - use customer of incoming message originator as new originator. Only for assigned to customer originators with one of the following type: ''User'', ''Asset'', ''Device''.</li><li><strong>Tenant</strong> - use current tenant as new originator.</li><li><strong>Related Entity</strong> - use related entity as new originator. Lookup based on configured relation query. If multiple related entities are found, only first entity is used as new originator, other entities are discarded.</li><li><strong>Alarm Originator</strong> - use alarm originator as new originator. Only if incoming message originator is alarm entity.</li><li><strong>Entity by name pattern</strong> - specify entity type and name pattern of new originator. Following entity types are supported: ''Device'', ''Asset'', ''Entity View'', ''Edge'' or ''User''.</li></ul>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Change message originator to Tenant/Customer/Related Entity/Alarm Originator/Entity by name pattern.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"originatorSource":"CUSTOMER","relationsQuery":{"direction":"FROM","maxLevel":1,"filters":[{"relationType":"Contains","entityTypes":[],"negate":false}],"fetchLastLevelOnly":false},"entityType":null,"entityNamePattern":null},"uiResources":[],"configDirective":"tbTransformationNodeChangeOriginatorConfig","icon":"find_replace","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/change-originator/"}}', 0, 'change originator', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfe279a0-6570-11f1-9578-071530b96ddb', 1781167089210, NULL, 'org.thingsboard.rule.engine.gcp.pubsub.TbPubSubNode', '{"nodeDefinition":{"details":"Will publish message payload to the Google Cloud Platform PubSub topic. Outbound message will contain response fields (<code>messageId</code> in the Message Metadata from the GCP PubSub. <b>messageId</b> field can be accessed with <code>metadata.messageId</code>.","description":"Publish message to the Google Cloud PubSub","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"projectId":"my-google-cloud-project-id","topicName":"my-pubsub-topic-name","messageAttributes":{},"serviceAccountKey":null,"serviceAccountKeyFileName":null},"uiResources":[],"configDirective":"tbExternalNodePubSubConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/gcp-pubsub/"}}', 0, 'gcp pubsub', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfe47570-6570-11f1-9578-071530b96ddb', 1781167089223, NULL, 'org.thingsboard.rule.engine.metadata.CalculateDeltaNode', '{"nodeDefinition":{"details":"Useful for metering use cases, when you need to calculate consumption based on pulse counter reading.<br><br>Output connections: <code>Success</code>, <code>Other</code> or <code>Failure</code>.","description":"Calculates delta and amount of time passed between previous timeseries key reading and current value for this key from the incoming message","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure","Other"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"inputValueKey":"pulseCounter","outputValueKey":"delta","useCache":true,"addPeriodBetweenMsgs":false,"periodValueKey":"periodInMs","round":null,"tellFailureIfDeltaIsNegative":true,"excludeZeroDeltas":false},"uiResources":[],"configDirective":"tbEnrichmentNodeCalculateDeltaConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/calculate-delta/"}}', 1, 'calculate delta', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff23110-6570-11f1-9578-071530b96ddb', 1781167089313, NULL, 'org.thingsboard.rule.engine.action.TbUnassignFromCustomerNode', '{"nodeDefinition":{"details":"If the message originator is not assigned to any customer, rule node will do nothing. <br><br>If the incoming message originator is a dashboard, will try to search for the customer by title specified in the configuration. If customer doesn''t exist, the exception will be thrown. Otherwise will unassign the dashboard from retrieved customer.<br><br>Other entities can be assigned only to one customer, so specified customer title in the configuration will be ignored if the originator isn''t a dashboard.","description":"Unassign message originator entity from customer","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"customerNamePattern":""},"uiResources":[],"configDirective":"tbActionNodeUnAssignToCustomerConfig","icon":"remove_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/unassign-from-customer/"}}', 1, 'unassign from customer', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfe75ba0-6570-11f1-9578-071530b96ddb', 1781167089242, NULL, 'org.thingsboard.rule.engine.metadata.TbGetDeviceAttrNode', '{"nodeDefinition":{"details":"Related device lookup based on the configured relation query. If multiple related devices are found, only first device is used for message enrichment, other entities are discarded. Useful when you need to retrieve attributes and/or latest telemetry values from device that has a relation to the message originator and use them for further message processing.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Add originators related device attributes and/or latest telemetry values into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","clientAttributeNames":[],"sharedAttributeNames":[],"serverAttributeNames":[],"latestTsKeyNames":[],"tellFailureIfAbsent":true,"getLatestValueWithTs":false,"deviceRelationsQuery":{"direction":"FROM","maxLevel":1,"relationType":"Contains","deviceTypes":["default"],"fetchLastLevelOnly":false}},"uiResources":[],"configDirective":"tbEnrichmentNodeDeviceAttributesConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/related-device-attributes/"}}', 1, 'related device attributes', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfe95770-6570-11f1-9578-071530b96ddb', 1781167089255, NULL, 'org.thingsboard.rule.engine.action.TbCreateRelationNode', '{"nodeDefinition":{"details":"Useful when you need to create relations between entities dynamically depending on incoming message payload, message originator type, name, etc.<br><br>Target entity configuration: <ul><li><strong>Device</strong> - use a device with the specified name as the target entity to create a relation with. When selected, rule node allows us to use advanced mode to enable device creation if it doesn''t exist. In advanced mode, device profile name should be specified.</li><li><strong>Asset</strong> - use an asset with the specified name as the target entity to create a relation with. When selected, rule node allows us to use advanced mode to enable device creation if it doesn''t exist. In advanced mode, asset profile name should be specified.</li><li><strong>Entity View</strong> - use entity view with the specified name as the target entity to create a relation with.</li><li><strong>Tenant</strong> - use current tenant as target entity to create a relation with.</li><li><strong>Customer</strong> - use customer with the specified title as the target entity to create a relation with. When selected, rule node allows us to use advanced mode to enable customer creation if it doesn''t exist.</li><li><strong>Dashboard</strong> - use a dashboard with the specified title as the target entity to create a relation with.</li><li><strong>User</strong> - use a user with the specified email as the target entity to create a relation with.</li><li><strong>Edge</strong> - use an edge with the specified name as the target entity to create a relation with.</li></ul>Advanced settings: <ul><li><strong>Remove current relations</strong> - removes current relations with originator of the incoming message based on direction and type. Useful in GPS tracking use cases where relation acts as a temporary indicator of a tracker presence in specific geofence.</li><li><strong>Change originator to target entity</strong> - useful when you need to process submitted message as a message from target entity.</li></ul>Output connections: <code>Success</code> - if the relation already exists or successfully created, otherwise <code>Failure</code>.","description":"Finds target entity specified in the configuration and creates a relation with the incoming message originator based on the configured direction and type.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"direction":"FROM","relationType":"Contains","entityType":null,"entityNamePattern":"","entityTypePattern":null,"createEntityIfNotExists":false,"changeOriginatorToRelatedEntity":false,"removeCurrentRelations":false},"uiResources":[],"configDirective":"tbActionNodeCreateRelationConfig","icon":"add_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/create-relation/"}}', 1, 'create relation', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfeb7a50-6570-11f1-9578-071530b96ddb', 1781167089269, NULL, 'org.thingsboard.rule.engine.geo.TbGpsGeofencingFilterNode', '{"nodeDefinition":{"details":"Extracts latitude and longitude parameters from the incoming message and checks them according to configured perimeter. </br>Configuration:</br></br><ul><li>Latitude key name - name of the message field that contains location latitude;</li><li>Longitude key name - name of the message field that contains location longitude;</li><li>Perimeter type - Polygon or Circle;</li><li>Fetch perimeter from message metadata - checkbox to load perimeter from message metadata;    Enable if your perimeter is specific to device/asset and you store it as device/asset attribute;</li><li>Perimeter key name - name of the metadata key that stores perimeter information;</li><li>For Polygon perimeter type: <ul>    <li>Polygon definition - string that contains array of coordinates in the following format: [[lat1, lon1],[lat2, lon2],[lat3, lon3], ... , [latN, lonN]]</li></ul></li><li>For Circle perimeter type: <ul>   <li>Center latitude - latitude of the circle perimeter center;</li>   <li>Center longitude - longitude of the circle perimeter center;</li>   <li>Range - value of the circle perimeter range, double-precision floating-point value;</li>   <li>Range units - one of: Meter, Kilometer, Foot, Mile, Nautical Mile;</li></ul></li></ul></br>Rule node will use default metadata key names, if the \"Fetch perimeter from message metadata\" is enabled and \"Perimeter key name\" is not configured. Default metadata key names for polygon perimeter type is \"perimeter\". Default metadata key names for circle perimeter are: \"centerLatitude\", \"centerLongitude\", \"range\", \"rangeUnit\".</br></br>Structure of the circle perimeter definition (stored in server-side attribute, for example):</br></br>{\"latitude\":  48.198618758582384, \"longitude\": 24.65322245153503, \"radius\":  100.0, \"radiusUnit\": \"METER\" }</br></br>Available radius units: METER, KILOMETER, FOOT, MILE, NAUTICAL_MILE;<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Filter incoming messages by GPS based geofencing","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"latitudeKeyName":"latitude","longitudeKeyName":"longitude","perimeterType":"POLYGON","fetchPerimeterInfoFromMessageMetadata":true,"perimeterKeyName":"ss_perimeter","polygonsDefinition":null,"centerLatitude":null,"centerLongitude":null,"range":null,"rangeUnit":null},"uiResources":[],"configDirective":"tbFilterNodeGpsGeofencingConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/gps-geofencing-filter/"}}', 0, 'gps geofencing filter', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfed2800-6570-11f1-9578-071530b96ddb', 1781167089280, NULL, 'org.thingsboard.rule.engine.transform.TbSplitArrayMsgNode', '{"nodeDefinition":{"details":"Splits an array message into individual elements, with each element sent as a separate message. All outbound messages will have the same type and metadata as the original array message.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Split array message into several messages","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"content_copy","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/split-array-msg/"}}', 0, 'split array msg', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfeed5b0-6570-11f1-9578-071530b96ddb', 1781167089291, NULL, 'org.thingsboard.rule.engine.action.TbAssignToCustomerNode', '{"nodeDefinition":{"details":"Finds target customer by title and assign message originator entity to this customer. Rule node will create a new customer if it doesn''t exist, and ''Create new customer if it doesn''t exist'' enabled.","description":"Assign message originator entity to customer","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"customerNamePattern":"","createCustomerIfNotExists":false},"uiResources":[],"configDirective":"tbActionNodeAssignToCustomerConfig","icon":"add_circle","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/assign-to-customer/"}}', 1, 'assign to customer', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff08360-6570-11f1-9578-071530b96ddb', 1781167089302, NULL, 'org.thingsboard.rule.engine.mail.TbMsgToEmailNode', '{"nodeDefinition":{"details":"Transforms message to email message. If transformation completed successfully output message type will be set to <code>SEND_EMAIL</code>.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Transforms message to email message","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fromTemplate":"info@testmail.org","toTemplate":"${userEmail}","ccTemplate":null,"bccTemplate":null,"subjectTemplate":"Device ${deviceType} temperature high","bodyTemplate":"Device ${deviceName} has high temperature $[temperature]","isHtmlTemplate":null,"mailBodyType":"false"},"uiResources":[],"configDirective":"tbTransformationNodeToEmailConfig","icon":"email","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/to-email/"}}', 0, 'to email', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff3dec0-6570-11f1-9578-071530b96ddb', 1781167089324, NULL, 'org.thingsboard.rule.engine.flow.TbRuleChainInputNode', '{"nodeDefinition":{"details":"The incoming message is forwarded to the input node of target rule chain. If ''Forward message to the originator''s default rule chain'' is enabled, then target rule chain might be resolved dynamically based on incoming message originator. In this case rule chain specified in the configuration will be used as fallback rule chain.<br><br>Output connections: <i>Any connection(s) produced by output node(s) in the target rule chain.</i>","description":"Transfers the message to another rule chain","inEnabled":true,"outEnabled":true,"relationTypes":["Failure"],"customRelations":true,"ruleChainNode":true,"defaultConfiguration":{"ruleChainId":null,"forwardMsgToDefaultRuleChain":false},"uiResources":[],"configDirective":"tbFlowNodeRuleChainInputConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/flow/rule-chain/"}}', 1, 'rule chain', 'TENANT', 'FLOW', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff58c70-6570-11f1-9578-071530b96ddb', 1781167089335, NULL, 'org.thingsboard.rule.engine.flow.TbAckNode', '{"nodeDefinition":{"details":"After acknowledgement, the message is pushed to related rule nodes. Useful if you don''t care what happens to this message next.","description":"Acknowledges the incoming message","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/flow/acknowledge/"}}', 0, 'acknowledge', 'TENANT', 'FLOW', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff73a20-6570-11f1-9578-071530b96ddb', 1781167089346, NULL, 'org.thingsboard.rule.engine.metadata.TbGetTenantDetailsNode', '{"nodeDefinition":{"details":"Useful when we need to retrieve contact information from your tenant such as email, phone, address, etc., for notifications via email, SMS, and other notification providers.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator tenant details into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"DATA","detailsList":[]},"uiResources":[],"configDirective":"tbEnrichmentNodeEntityDetailsConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/tenant-details/"}}', 1, 'tenant details', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dff935f0-6570-11f1-9578-071530b96ddb', 1781167089359, NULL, 'org.thingsboard.rule.engine.transform.TbCopyKeysNode', '{"nodeDefinition":{"details":"Copies key-value pairs from the message to message metadata, or vice-versa, according to the configured direction and keys. Regular expressions can be used to define which keys-value pairs to copy. Any configured key not found in the source will be ignored.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Copies key-value pairs from message to message metadata or vice-versa.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"copyFrom":"DATA","keys":[]},"uiResources":[],"configDirective":"tbTransformationNodeCopyKeysConfig","icon":"content_copy","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/transformation/copy-key-value-pairs/"}}', 2, 'copy key-value pairs', 'TENANT', 'TRANSFORMATION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dffd54a0-6570-11f1-9578-071530b96ddb', 1781167089386, NULL, 'org.thingsboard.rule.engine.mqtt.azure.TbAzureIotHubNode', '{"nodeDefinition":{"details":"Will publish message payload to the Azure IoT Hub with QoS <b>AT_LEAST_ONCE</b>.","description":"Publish messages to the Azure IoT Hub","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"topicPattern":"devices/<device_id>/messages/events/","host":"<iot-hub-name>.azure-devices.net","port":8883,"connectTimeoutSec":10,"clientId":null,"appendClientIdSuffix":false,"retainedMessage":false,"cleanSession":true,"ssl":true,"parseToPlainText":false,"protocolVersion":"MQTT_3_1_1","credentials":{"type":"sas","caCert":null,"cert":null,"privateKey":null,"password":null,"sasKey":null}},"uiResources":[],"configDirective":"tbExternalNodeAzureIotHubConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/azure-iot-hub/"}}', 1, 'azure iot hub', 'TENANT', 'EXTERNAL', 'SINGLETON', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('dfff7780-6570-11f1-9578-071530b96ddb', 1781167089400, NULL, 'org.thingsboard.rule.engine.aws.sns.TbSnsNode', '{"nodeDefinition":{"details":"Will publish message payload to the AWS SNS topic. Outbound message will contain response fields (<code>messageId</code>, <code>requestId</code>) in the Message Metadata from the AWS SNS. For example <b>requestId</b> field can be accessed with <code>metadata.requestId</code>.","description":"Publish message to the AWS SNS","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"topicArnPattern":"arn:aws:sns:us-east-1:123456789012:MyNewTopic","accessKeyId":null,"secretAccessKey":null,"region":"us-east-1"},"uiResources":[],"configDirective":"tbExternalNodeSnsConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/aws-sns/"}}', 0, 'aws sns', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e000fe20-6570-11f1-9578-071530b96ddb', 1781167089410, NULL, 'org.thingsboard.rule.engine.transaction.TbSynchronizationEndNode', '{"nodeDefinition":{"details":"","description":"This Node is now deprecated. Use \"Checkpoint\" instead.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"version":0},"uiResources":[],"configDirective":"tbNodeEmptyConfig","icon":"","iconUrl":"","docUrl":""}}', 0, 'synchronization end', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0032100-6570-11f1-9578-071530b96ddb', 1781167089424, NULL, 'org.thingsboard.rule.engine.notification.TbNotificationNode', '{"nodeDefinition":{"details":"Will send notification to the specified targets using the template","description":"Sends notification to targets using the template","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"targets":null,"templateId":null},"uiResources":[],"configDirective":"tbExternalNodeNotificationConfig","icon":"notifications","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/send-notification/"}}', 0, 'send notification', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0051cd0-6570-11f1-9578-071530b96ddb', 1781167089437, NULL, 'org.thingsboard.rule.engine.kafka.TbKafkaNode', '{"nodeDefinition":{"details":"Will send record via Kafka producer to Kafka server. Outbound message will contain response fields (<code>offset</code>, <code>partition</code>, <code>topic</code>) from the Kafka in the Message Metadata. For example <b>partition</b> field can be accessed with <code>metadata.partition</code>.","description":"Publish messages to Kafka server","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"topicPattern":"my-topic","keyPattern":null,"bootstrapServers":"localhost:9092","retries":0,"batchSize":16384,"linger":0,"bufferMemory":33554432,"acks":"-1","otherProperties":{},"addMetadataKeyValuesAsKafkaHeaders":false,"kafkaHeadersCharset":"UTF-8"},"uiResources":[],"configDirective":"tbExternalNodeKafkaConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/kafka/"}}', 1, 'kafka', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e00766c0-6570-11f1-9578-071530b96ddb', 1781167089452, NULL, 'org.thingsboard.rule.engine.telemetry.TbMsgAttributesNode', '{"nodeDefinition":{"details":"Node performs three <strong>actions:</strong>\n<ul>\n  <li><strong>Attributes:</strong> save attribute data to a database.</li>\n  <li><strong>WebSockets:</strong> notify WebSockets subscriptions about attribute data updates.</li>\n  <li><strong>Calculated fields:</strong> notify calculated fields about attribute data updates.</li>\n</ul>\n\nFor each <em>action</em>, three <strong>processing strategies</strong> are available:\n<ul>\n  <li><strong>On every message:</strong> perform the action for every message.</li>\n  <li><strong>Deduplicate:</strong> perform the action only for the first message from a particular originator within a configurable interval.</li>\n  <li><strong>Skip:</strong> never perform the action.</li>\n</ul>\n\n<strong>Processing strategies</strong> are configured using <em>processing settings</em>, which support two modes:\n<ul>\n  <li><strong>Basic</strong>\n    <ul>\n      <li><strong>On every message:</strong> applies the \"On every message\" strategy to all actions.</li>\n      <li><strong>Deduplicate:</strong> applies the \"Deduplicate\" strategy (with a specified interval) to all actions.</li>\n      <li><strong>WebSockets only:</strong> for all actions except WebSocket notifications, the \"Skip\" strategy is applied, while WebSocket notifications use the \"On every message\" strategy.</li>\n    </ul>\n  </li>\n  <li><strong>Advanced:</strong> configure each action’s strategy independently.</li>\n</ul>\n\nThe node supports three attribute scopes: <strong>Client attributes</strong>, <strong>Shared attributes</strong>, and <strong>Server attributes</strong>.\nYou can set the default scope in the node configuration, or override it by specifying a valid <code>scope</code> property in the message metadata.\n<br><br>\nAdditionally:\n<ul>\n  <li>If <b>Save attributes only if the value changes</b> is enabled, the rule node compares the received attribute value with the current stored value and skips the save operation if they match.</li>\n  <li>If <b>Send attributes updated notification</b> is enabled, the rule node will put the <b>Attributes Updated</b> event for <code>SHARED_SCOPE</code> and <code>SERVER_SCOPE</code> attribute updates to the queue named <code>Main</code>.</li>\n  <li>If <b>Force notification to the device</b> is enabled, then rule node will always notify device about <code>SHARED_SCOPE</code> attribute updates, regardless of the value of <code>notifyDevice</code> metadata property.</li>\n</ul>\n\nThis node expects messages of type <code>POST_ATTRIBUTES_REQUEST</code>.\n<br><br>\nOutput connections: <code>Success</code>, <code>Failure</code>.\n","description":"Saves attribute data with a configurable scope and according to configured processing strategies.\n","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"processingSettings":{"type":"ON_EVERY_MESSAGE"},"scope":"SERVER_SCOPE","notifyDevice":false,"sendAttributesUpdatedNotification":false,"updateAttributesOnlyOnValueChange":true},"uiResources":[],"configDirective":"tbActionNodeAttributesConfig","icon":"file_upload","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/save-attributes/"}}', 3, 'save attributes', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0096290-6570-11f1-9578-071530b96ddb', 1781167089465, NULL, 'org.thingsboard.rule.engine.notification.TbSlackNode', '{"nodeDefinition":{"details":"Sends message to a Slack channel or user","description":"Send message via Slack","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"botToken":"xoxb-","useSystemSettings":true,"messageTemplate":"Device ${deviceId}: temperature is $[temperature]","conversationType":"PUBLIC_CHANNEL","conversation":null},"uiResources":[],"configDirective":"tbExternalNodeSlackConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/send-to-slack/"}}', 0, 'send to slack', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e00b1040-6570-11f1-9578-071530b96ddb', 1781167089476, NULL, 'org.thingsboard.rule.engine.delay.TbMsgDelayNode', '{"nodeDefinition":{"details":"Delays messages for a configurable period. Please note, this node acknowledges the message from the current queue (message will be removed from queue). Deprecated because the acknowledged message still stays in memory (to be delayed) and this does not guarantee that message will be processed even if the \"retry failures and timeouts\" processing strategy will be chosen.","description":"Delays incoming message (deprecated)","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"periodInSeconds":60,"maxPendingMsgs":1000,"periodInSecondsPattern":null,"useMetadataPeriodInSecondsPatterns":false},"uiResources":[],"configDirective":"tbActionNodeMsgDelayConfig","icon":"pause","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/delay/"}}', 0, 'delay (deprecated)', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e00ce500-6570-11f1-9578-071530b96ddb', 1781167089488, NULL, 'org.thingsboard.rule.engine.action.TbDeviceStateNode', '{"nodeDefinition":{"details":"If incoming message originator is a device, registers configured event for that device in the Device State Service, which sends appropriate message to the Rule Engine. If metadata <code>ts</code> property is present, it will be used as event timestamp. Otherwise, the message timestamp will be used. If originator entity type is not <code>DEVICE</code> or unexpected error happened during processing, then incoming message is forwarded using <code>Failure</code> chain. If rate of connectivity events for a given originator is too high, then incoming message is forwarded using <code>Rate limited</code> chain. <br>Supported device connectivity events are:<ul><li>Connect event</li><li>Disconnect event</li><li>Activity event</li><li>Inactivity event</li></ul>This node is particularly useful when device isn''t using transports to receive data, such as when fetching data from external API or computing new data within the rule chain.","description":"Triggers device connectivity events","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure","Rate limited"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"event":"ACTIVITY_EVENT"},"uiResources":[],"configDirective":"tbActionNodeDeviceStateConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/device-state/"}}', 0, 'device state', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0121520-6570-11f1-9578-071530b96ddb', 1781167089522, NULL, 'org.thingsboard.rule.engine.filter.TbCheckAlarmStatusNode', '{"nodeDefinition":{"details":"Checks the alarm status to match one of the specified statuses.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>.","description":"Checks alarm status.","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"alarmStatusList":["ACTIVE_ACK","ACTIVE_UNACK"]},"uiResources":[],"configDirective":"tbFilterNodeCheckAlarmStatusConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/alarm-status-filter/"}}', 0, 'alarm status filter', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e01410f0-6570-11f1-9578-071530b96ddb', 1781167089535, NULL, 'org.thingsboard.rule.engine.rabbitmq.TbRabbitMqNode', '{"nodeDefinition":{"details":"Will publish message payload to RabbitMQ queue.","description":"Publish messages to the RabbitMQ","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"exchangeNamePattern":"","routingKeyPattern":"","messageProperties":null,"host":null,"port":5672,"virtualHost":"/","username":"guest","password":"guest","automaticRecoveryEnabled":false,"connectionTimeout":60000,"handshakeTimeout":10000,"clientProperties":{}},"uiResources":[],"configDirective":"tbExternalNodeRabbitMqConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/rabbitmq/"}}', 0, 'rabbitmq', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e015bea0-6570-11f1-9578-071530b96ddb', 1781167089546, NULL, 'org.thingsboard.rule.engine.mqtt.TbMqttNode', '{"nodeDefinition":{"details":"Will publish message payload to the MQTT broker with QoS <b>AT_LEAST_ONCE</b>.","description":"Publish messages to the MQTT broker","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"topicPattern":"my-topic","host":null,"port":1883,"connectTimeoutSec":10,"clientId":null,"appendClientIdSuffix":false,"retainedMessage":false,"cleanSession":true,"ssl":false,"parseToPlainText":false,"protocolVersion":"MQTT_3_1_1","credentials":{"type":"anonymous"}},"uiResources":[],"configDirective":"tbExternalNodeMqttConfig","icon":"call_split","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/mqtt/"}}', 2, 'mqtt', 'TENANT', 'EXTERNAL', 'USER_PREFERENCE', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0174540-6570-11f1-9578-071530b96ddb', 1781167089556, NULL, 'org.thingsboard.rule.engine.rpc.TbSendRPCReplyNode', '{"nodeDefinition":{"details":"Expects messages with any message type. Will forward message body to the device.","description":"Sends reply to RPC call from device","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"serviceIdMetaDataAttribute":"serviceId","sessionIdMetaDataAttribute":"sessionId","requestIdMetaDataAttribute":"requestId"},"uiResources":[],"configDirective":"tbActionNodeRpcReplyConfig","icon":"call_merge","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/rpc-call-reply/"}}', 0, 'rpc call reply', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e0191a00-6570-11f1-9578-071530b96ddb', 1781167089568, NULL, 'org.thingsboard.rule.engine.rest.TbRestApiCallNode', '{"nodeDefinition":{"details":"Will invoke REST API call <code>GET | POST | PUT | DELETE</code> to external REST server. Message payload added into Request body. Configured attributes can be added into Headers from Message Metadata. Outbound message will contain response fields (<code>status</code>, <code>statusCode</code>, <code>statusReason</code> and response <code>headers</code>) in the Message Metadata. Response body saved in outbound Message payload. For example <b>statusCode</b> field can be accessed with <code>metadata.statusCode</code>.<br/><b>Note-</b> if you use system proxy properties, the next system proxy properties should be added: \"http.proxyHost\" and \"http.proxyPort\" or  \"https.proxyHost\" and \"https.proxyPort\" or \"socksProxyHost\" and \"socksProxyPort\",and if your proxy with auth, the next ones  should be added: \"tb.proxy.user\" and \"tb.proxy.password\" to the thingsboard.conf file.","description":"Invoke REST API calls to external REST server","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"restEndpointUrlPattern":"http://localhost/api","requestMethod":"POST","headers":{"Content-Type":"application/json"},"useSimpleClientHttpFactory":false,"readTimeoutMs":0,"maxParallelRequestsCount":0,"parseToPlainText":false,"enableProxy":false,"useSystemProxyProperties":false,"proxyHost":null,"proxyPort":0,"proxyUser":null,"proxyPassword":null,"proxyScheme":null,"credentials":{"type":"anonymous"},"ignoreRequestBody":false,"maxInMemoryBufferSizeInKb":256},"uiResources":[],"configDirective":"tbExternalNodeRestApiCallConfig","icon":"","iconUrl":"data:image/svg+xml;base64,","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/external/rest-api-call/"}}', 3, 'rest api call', 'TENANT', 'EXTERNAL', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e01aa0a0-6570-11f1-9578-071530b96ddb', 1781167089578, NULL, 'org.thingsboard.rule.engine.metadata.TbGetCustomerAttributeNode', '{"nodeDefinition":{"details":"Useful in multi-customer solutions where each customer has a different configuration or threshold set that is stored as customer attributes or telemetry data and used for dynamic message filtering, transformation, or actions such as alarm creation if the threshold is exceeded.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator customer attributes or latest telemetry into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","dataMapping":{"alarmThreshold":"threshold"},"dataToFetch":"ATTRIBUTES"},"uiResources":[],"configDirective":"tbEnrichmentNodeCustomerAttributesConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/customer-attributes/"}}', 1, 'customer attributes', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e01c4e50-6570-11f1-9578-071530b96ddb', 1781167089589, NULL, 'org.thingsboard.rule.engine.metadata.TbGetOriginatorFieldsNode', '{"nodeDefinition":{"details":"Fetches fields values specified in the mapping. If specified field is not part of originator fields it will be ignored. Useful when you need to retrieve originator fields and use them for further message processing.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator fields values into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","dataMapping":{"name":"originatorName","type":"originatorType"},"ignoreNullStrings":false},"uiResources":[],"configDirective":"tbEnrichmentNodeOriginatorFieldsConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/originator-fields/"}}', 1, 'originator fields', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e01dd4f0-6570-11f1-9578-071530b96ddb', 1781167089599, NULL, 'org.thingsboard.rule.engine.filter.TbCheckMessageNode', '{"nodeDefinition":{"details":"By default, the rule node checks that all specified fields are present. Uncheck the ''Check that all selected fields are present'' if the presence of at least one field is sufficient.<br><br>Output connections: <code>True</code>, <code>False</code>, <code>Failure</code>","description":"Checks the presence of the specified fields in the message and/or metadata.","inEnabled":true,"outEnabled":true,"relationTypes":["True","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"messageNames":[],"metadataNames":[],"checkAllKeys":true},"uiResources":[],"configDirective":"tbFilterNodeCheckMessageConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/filter/check-fields-presence/"}}', 0, 'check fields presence', 'TENANT', 'FILTER', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e01f3480-6570-11f1-9578-071530b96ddb', 1781167089608, NULL, 'org.thingsboard.rule.engine.metadata.TbGetCustomerDetailsNode', '{"nodeDefinition":{"details":"Useful in multi-customer solutions where we need dynamically use customer contact information such as email, phone, address, etc., for notifications via email, SMS, and other notification providers.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator customer details into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"DATA","detailsList":[]},"uiResources":[],"configDirective":"tbEnrichmentNodeEntityDetailsConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/customer-details/"}}', 1, 'customer details', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e020bb20-6570-11f1-9578-071530b96ddb', 1781167089618, NULL, 'org.thingsboard.rule.engine.action.TbSaveToCustomCassandraTableNode', '{"nodeDefinition":{"details":"Administrator should set the custom table name without prefix: <b>cs_tb_</b>. <br>Administrator can configure the mapping between the Message field names and Table columns name.<br><b>Note:</b>If the mapping key is <b>$entity_id</b>, that is identified by the Message Originator, then to the appropriate column name(mapping value) will be write the message originator id.<br><br>If specified message field does not exist or is not a JSON Primitive, the outbound message will be routed via <b>failure</b> chain, otherwise, the message will be routed via <b>success</b> chain.","description":"Node stores data from incoming Message payload to the Cassandra database into the predefined custom table that should have <b>cs_tb_</b> prefix, to avoid the data insertion to the common TB tables.<br><b>Note:</b> rule node can be used only for Cassandra DB.","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"tableName":"","fieldsMapping":{"":""},"defaultTtl":0},"uiResources":[],"configDirective":"tbActionNodeCustomTableConfig","icon":"file_upload","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/save-to-custom-table/"}}', 1, 'save to custom table', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e02268d0-6570-11f1-9578-071530b96ddb', 1781167089629, NULL, 'org.thingsboard.rule.engine.geo.TbGpsGeofencingActionNode', '{"nodeDefinition":{"details":"Extracts latitude and longitude parameters from incoming message and returns different events based on configuration parameters. <br><br>If an object with coordinates extracted from incoming message enters the geofence, sends a message with the type <code>Entered</code>. If an object leaves the geofence, sends a message with the type <code>Left</code>. If the presence monitoring strategy <b>\"On first message\"</b> is selected, sends messages via rule node connection type <code>Inside</code> or <code>Outside</code> only the first time the geofencing and duration conditions are satisfied; otherwise sends messages via rule node connection type <code>Success</code>. If the presence monitoring strategy <b>\"On each message\"</b> is selected, sends messages via rule node connection type <code>Inside</code> or <code>Outside</code> every time the geofencing condition is satisfied. <br><br>Output connections: <code>Entered</code>, <code>Left</code>, <code>Inside</code>, <code>Outside</code>, <code>Success</code>","description":"Produces incoming messages using GPS based geofencing","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Entered","Left","Inside","Outside","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"latitudeKeyName":"latitude","longitudeKeyName":"longitude","perimeterType":"POLYGON","fetchPerimeterInfoFromMessageMetadata":true,"perimeterKeyName":"ss_perimeter","polygonsDefinition":null,"centerLatitude":null,"centerLongitude":null,"range":null,"rangeUnit":null,"minInsideDuration":1,"minOutsideDuration":1,"minInsideDurationTimeUnit":"MINUTES","minOutsideDurationTimeUnit":"MINUTES","reportPresenceStatusOnEachMessage":true},"uiResources":[],"configDirective":"tbActionNodeGpsGeofencingConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/gps-geofencing-events/"}}', 1, 'gps geofencing events', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e023ef70-6570-11f1-9578-071530b96ddb', 1781167089639, NULL, 'org.thingsboard.rule.engine.metadata.TbGetTenantAttributeNode', '{"nodeDefinition":{"details":"Useful when you need to retrieve some common configuration or threshold set that is stored as tenant attributes or telemetry data and use it for further message processing.<br><br>Output connections: <code>Success</code>, <code>Failure</code>.","description":"Adds message originator tenant attributes or latest telemetry into message or message metadata","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"fetchTo":"METADATA","dataMapping":{"alarmThreshold":"threshold"},"dataToFetch":"ATTRIBUTES"},"uiResources":[],"configDirective":"tbEnrichmentNodeTenantAttributesConfig","icon":"","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/enrichment/tenant-attributes/"}}', 1, 'tenant attributes', 'TENANT', 'ENRICHMENT', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e025eb40-6570-11f1-9578-071530b96ddb', 1781167089652, NULL, 'org.thingsboard.rule.engine.action.TbCreateAlarmNode', '{"nodeDefinition":{"details":"Details - JS function that creates JSON object based on incoming message. This object will be added into Alarm.details field.\nNode output:\nIf alarm was not created, original message is returned. Otherwise new Message returned with type ''ALARM'', Alarm object in ''msg'' property and ''metadata'' will contains one of those properties ''isNewAlarm/isExistingAlarm''. Message payload can be accessed via <code>msg</code> property. For example <code>''temperature = '' + msg.temperature ;</code>. Message metadata can be accessed via <code>metadata</code> property. For example <code>''name = '' + metadata.customerName;</code>.","description":"Create or Update Alarm","inEnabled":true,"outEnabled":true,"relationTypes":["Created","Updated","False","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"alarmType":"General Alarm","scriptLang":"TBEL","alarmDetailsBuildJs":"var details = {};\nif (metadata.prevAlarmDetails) {\n    details = JSON.parse(metadata.prevAlarmDetails);\n    //remove prevAlarmDetails from metadata\n    delete metadata.prevAlarmDetails;\n    //now metadata is the same as it comes IN this rule node\n}\n\n\nreturn details;","alarmDetailsBuildTbel":"var details = {};\nif (metadata.prevAlarmDetails != null) {\n    details = JSON.parse(metadata.prevAlarmDetails);\n    //remove prevAlarmDetails from metadata\n    metadata.remove(''prevAlarmDetails'');\n    //now metadata is the same as it comes IN this rule node\n}\n\n\nreturn details;","severity":"CRITICAL","propagate":false,"propagateToOwner":false,"propagateToTenant":false,"useMessageAlarmData":false,"overwriteAlarmDetails":false,"dynamicSeverity":false,"relationTypes":[]},"uiResources":[],"configDirective":"tbActionNodeCreateAlarmConfig","icon":"notifications_active","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/create-alarm/"}}', 0, 'create alarm', 'TENANT', 'ACTION', 'ENABLED', 'f');
INSERT INTO "component_descriptor" ("id", "created_time", "actions", "clazz", "configuration_descriptor", "configuration_version", "name", "scope", "type", "clustering_mode", "has_queue_name") VALUES ('e00ee0d0-6570-11f1-9578-071530b96ddb', 0, NULL, 'org.thingsboard.rule.engine.telemetry.TbMsgTimeseriesNode', '{"nodeDefinition":{"details":"Node performs four <strong>actions:</strong>\n<ul>\n  <li><strong>Time series:</strong> save time series data to a <code>ts_kv</code> table in a DB.</li>\n  <li><strong>Latest values:</strong> save time series data to a <code>ts_kv_latest</code> table in a DB.</li>\n  <li><strong>WebSockets:</strong> notify WebSockets subscriptions about time series data updates.</li>\n  <li><strong>Calculated fields:</strong> notify calculated fields about time series data updates.</li>\n</ul>\n\nFor each <em>action</em>, three <strong>processing strategies</strong> are available:\n<ul>\n  <li><strong>On every message:</strong> perform the action for every message.</li>\n  <li><strong>Deduplicate:</strong> perform the action only for the first message from a particular originator within a configurable interval.</li>\n  <li><strong>Skip:</strong> never perform the action.</li>\n</ul>\n\n<strong>Processing strategies</strong> are configured using <em>processing settings</em>, which support two modes:\n<ul>\n  <li><strong>Basic</strong>\n    <ul>\n      <li><strong>On every message:</strong> applies the \"On every message\" strategy to all actions.</li>\n      <li><strong>Deduplicate:</strong> applies the \"Deduplicate\" strategy (with a specified interval) to all actions.</li>\n      <li><strong>WebSockets only:</strong> for all actions except WebSocket notifications, the \"Skip\" strategy is applied, while WebSocket notifications use the \"On every message\" strategy.</li>\n    </ul>\n  </li>\n  <li><strong>Advanced:</strong> configure each action’s strategy independently.</li>\n</ul>\n\nBy default, the timestamp is taken from <code>metadata.ts</code>. You can enable\n<em>Use server timestamp</em> to always use the current server time instead. This is particularly\nuseful in sequential processing scenarios where messages may arrive with out-of-order timestamps from\nmultiple sources. Note that the DB layer may ignore \"outdated\" records for attributes and latest values,\nso enabling <em>Use server timestamp</em> can ensure correct ordering.\n<br><br>\nThe TTL is taken first from <code>metadata.TTL</code>. If absent, the node configuration’s default\nTTL is used. If neither is set, the tenant profile default applies.\n<br><br>\nThis node expects messages of type <code>POST_TELEMETRY_REQUEST</code>.\n<br><br>\nOutput connections: <code>Success</code>, <code>Failure</code>.\n","description":"Saves time series data with a configurable TTL and according to configured processing strategies.\n","inEnabled":true,"outEnabled":true,"relationTypes":["Success","Failure"],"customRelations":false,"ruleChainNode":false,"defaultConfiguration":{"defaultTTL":0,"useServerTs":false,"processingSettings":{"type":"ON_EVERY_MESSAGE"}},"uiResources":[],"configDirective":"tbActionNodeTimeseriesConfig","icon":"file_upload","iconUrl":"","docUrl":"https://thingsboard.io/docs/user-guide/rule-engine-2-0/nodes/action/save-timeseries/"}}', 1, 'save time series', 'TENANT', 'ACTION', 'ENABLED', 'f');
